mapper.select:
SELECT DISTINCT 

FROM t_tran t
LEFT JOIN t_customer c ON t.customer_id = c.id
LEFT JOIN t_clue cl ON c.clue_id = cl.id
LEFT JOIN t_tran_product tp ON t.id = tp.tran_id
LEFT JOIN t_product p ON tp.product_id = p.id
LEFT JOIN t_tran_invoice ti ON t.id = ti.tran_id

  
    AND t.tran_no LIKE CONCAT('%', #{tranNo}, '%')
  
  
    AND t.customer_id = #{customerId}
  
  
    AND cl.full_name LIKE CONCAT('%', #{customerName}, '%')
  
  
    AND t.stage = #{stage}
  
  
    AND t.money >= #{minMoney}
  
  
    AND t.money <= #{maxMoney}
  
  
    AND t.expected_date >= #{expectedDateStart}
  
  
    AND t.expected_date <= #{expectedDateEnd}
  
  
    AND t.create_time >= #{createTimeStart}
  
  
    AND t.create_time <= #{createTimeEnd}
  
  
    AND t.create_by = #{createBy}
  
  
    AND tp.product_id = #{productId}
  
  
    AND p.name LIKE CONCAT('%', #{productName}, '%')
  
  
    AND ti.status = #{invoiceStatus}
  
  
    AND ${filterSQL}
  

ORDER BY t.create_time DESC
